import { useState, useRef } from "react";
import { useNavigate } from "react-router-dom";

export default function VerifyCodePage() {
  const navigate = useNavigate();
  const [digits, setDigits] = useState(["", "", "", "", "", ""]);
  const refs = useRef([]);

  function handleChange(val, i) {
    const d = val.replace(/\D/g, "").slice(-1);
    const next = [...digits];
    next[i] = d;
    setDigits(next);
    if (d && i < 5) refs.current[i + 1]?.focus();
  }

  function handleKeyDown(e, i) {
    if (e.key === "Backspace" && !digits[i] && i > 0) refs.current[i - 1]?.focus();
  }

  return (
    <div className="min-h-screen bg-cream flex flex-col">
      <div className="h-14 bg-white border-b border-gray-200 flex items-center justify-between px-8">
        <div className="flex items-center gap-2 cursor-pointer" onClick={() => navigate("/")}>
          <div className="w-8 h-8 bg-navy rounded-lg flex items-center justify-center text-white font-bold text-sm">A</div>
          <span className="font-semibold text-gray-900">WorkBridge DZ</span>
        </div>
        <button onClick={() => navigate(-1)} className="text-sm text-gray-400 hover:text-gray-900">← Back</button>
      </div>

      <div className="flex-1 flex flex-col items-center justify-center px-6 py-10 text-center">
        <div className="w-14 h-14 bg-blue-100 rounded-2xl flex items-center justify-center text-2xl mb-6">✉️</div>

        <h1 className="font-serif text-3xl font-normal mb-3">Check your email</h1>
        <p className="text-sm text-gray-500 mb-1">We sent a 6-digit verification code to</p>
        <p className="font-semibold text-gray-900 mb-8">ya***ne@gmail.com</p>

        {/* Step indicators */}
        <div className="flex items-center gap-3 mb-8">
          {[
            { n: "✓", label: "Email", done: true },
            { n: 2, label: "Verification", active: true },
            { n: 3, label: "New Password" },
          ].map((s, i) => (
            <div key={i} className="flex items-center gap-2">
              {i > 0 && <div className={`w-14 h-px ${s.done ? "bg-navy" : "bg-gray-200"}`} />}
              <div className={`w-7 h-7 rounded-full border flex items-center justify-center text-xs font-medium
                ${s.done ? "bg-navy border-navy text-white" : s.active ? "border-navy text-navy font-semibold bg-white" : "border-gray-200 text-gray-400 bg-white"}`}>
                {s.n}
              </div>
              <span className={`text-sm ${s.active ? "font-semibold text-gray-900" : "text-gray-400"}`}>{s.label}</span>
            </div>
          ))}
        </div>

        <div className="bg-white rounded-2xl border border-gray-200 p-8 w-full max-w-sm">
          <p className="text-sm font-medium mb-4 text-left">Enter 6-digit code</p>

          <div className="flex gap-2 mb-4">
            {digits.map((d, i) => (
              <input
                key={i}
                ref={(el) => (refs.current[i] = el)}
                type="text"
                inputMode="numeric"
                maxLength={1}
                value={d}
                onChange={(e) => handleChange(e.target.value, i)}
                onKeyDown={(e) => handleKeyDown(e, i)}
                className={`w-12 h-14 rounded-xl border text-center font-serif text-2xl outline-none transition-all
                  ${d ? "border-red/40 bg-red/5 text-navy" : "border-gray-200 bg-cream"}
                  focus:border-navy focus:bg-white`}
              />
            ))}
          </div>

          <div className="flex justify-between items-center mb-5">
            <span className="text-sm text-gray-500">⏱ Code expires in <strong className="text-gray-900">04:38</strong></span>
            <button className="text-sm text-navy font-medium hover:underline">Resend code</button>
          </div>

          <button className="w-full py-3.5 bg-red text-white rounded-full text-sm font-medium hover:bg-red-dark transition-all" onClick={() => navigate("/password-reset-success")}>
            Verify Code →
          </button>

          <p className="text-xs text-gray-400 text-center mt-4">
            Didn't receive the email? Check your spam folder or{" "}
            <span className="text-navy cursor-pointer hover:underline">try a different address</span>.
          </p>
        </div>
      </div>
    </div>
  );
}
